import csv
import io


def _num(s):
    return float(s.strip().replace(",", "."))


def carica_catalogo(testo):
    righe = csv.DictReader(io.StringIO(testo.strip()), delimiter=";")
    catalogo = {}
    for r in righe:
        if not r["nome"]:
            continue
        catalogo[r["nome"].strip()] = Materiale(r["nome"].strip(), _num(r["fy"]), _num(r["E"]), _num(r["rho"]))
    return catalogo
